/* =====================================================================
   APP
   ===================================================================== */
function App() {
  const [scrolled, setScrolled] = useState(false);
  const [activeId, setActiveId] = useState("");
  const progressRef = useRef(null);

  // Persist theme preference across reloads
  const [darkMode, setDarkMode] = useState(() => {
    if (typeof window === "undefined") return true;
    const saved = window.localStorage.getItem("pm-theme");
    if (saved === "light") return false;
    if (saved === "dark") return true;
    return true; // default: dark theme
  });

  // Nav visibility + scroll progress line (rAF-throttled)
  useEffect(() => {
    let raf = 0;
    const update = () => {
      raf = 0;
      const y = window.scrollY;
      setScrolled(y > 40);
      if (y < window.innerHeight * 0.8) setActiveId("");
      const max = document.documentElement.scrollHeight - window.innerHeight;
      if (progressRef.current) {
        progressRef.current.style.transform = `scaleX(${max > 0 ? Math.min(1, y / max) : 0})`;
      }
    };
    const onScroll = () => {
      if (!raf) raf = requestAnimationFrame(update);
    };
    update();
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);
    return () => {
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
      if (raf) cancelAnimationFrame(raf);
    };
  }, []);

  // Highlight the nav link for the section in the middle of the screen
  useEffect(() => {
    const els = ["about", "skills", "work", "hint", "contact"]
      .map((id) => document.getElementById(id))
      .filter(Boolean);
    const io = new IntersectionObserver(
      (entries) => {
        entries.forEach((e) => {
          if (e.isIntersecting) setActiveId(e.target.id);
        });
      },
      { rootMargin: "-45% 0px -50% 0px", threshold: 0 }
    );
    els.forEach((el) => io.observe(el));
    return () => io.disconnect();
  }, []);

  useEffect(() => {
    if (typeof window === "undefined") return;
    window.localStorage.setItem("pm-theme", darkMode ? "dark" : "light");
    document.documentElement.dataset.theme = darkMode ? "dark" : "light";
  }, [darkMode]);

  const toggleTheme = () => setDarkMode((prev) => !prev);

  return (
    <div className={`portfolio ${darkMode ? "dark" : "light"}`}>
      <ChatBot darkMode={darkMode} />

      {/* NAV */}
      <nav className={`nav ${scrolled ? "nav-solid" : ""}`} aria-label="Primary">
        <a className="brand" href="#top" data-testid="nav-brand">
          <span className="brand-mark">PM</span>
          <span className="brand-name">Pushkar Mishra</span>
        </a>

        <div className="nav-links">
          {NAV_ITEMS.map(({ id, label }) => (
            <a
              key={id}
              href={`#${id}`}
              className={`nav-link ${activeId === id ? "is-active" : ""}`}
            >
              {activeId === id && (
                <motion.span
                  layoutId="nav-active-pill"
                  className="nav-link-pill"
                  transition={{ type: "spring", stiffness: 420, damping: 36 }}
                />
              )}
              <span className="nav-link-label">{label}</span>
            </a>
          ))}

          <button
            type="button"
            className="theme-toggle"
            onClick={toggleTheme}
            aria-label={darkMode ? "Switch to light mode" : "Switch to dark mode"}
            title={darkMode ? "Switch to light mode" : "Switch to dark mode"}
            data-testid="theme-toggle-button"
          >
            <span className="theme-toggle-track">
              <span className="theme-toggle-thumb">
                {darkMode ? <Moon size={12} /> : <Sun size={12} />}
              </span>
            </span>
          </button>

          <a href="#contact" className="nav-cta">
            Let's talk <ArrowUpRight size={14} />
          </a>
        </div>

        <span className="nav-progress" ref={progressRef} aria-hidden="true" />
      </nav>

      {/* HERO — unchanged */}
      <header id="top" className="hero">
        <div className="unicorn-wrap">
          <UnicornScene darkMode={darkMode} />
        </div>

        <div className="hero-overlay">
          <h1 key={darkMode ? "title-dark" : "title-light"} className="hero-title glass-text">
            Pushkar Mishra
          </h1>
          <p className="hero-sub">Designer · Developer · Dream Architect</p>
        </div>

        <div className="scroll-hint">
          <span>Scroll</span>
          <div className="scroll-line" />
        </div>
      </header>

      {/* EARTH JOURNEY — replaces the old "below the clouds" sky */}
      <EarthJourney />

      {/* MAIN CONTENT */}
      <main className={`content ${darkMode ? "dark-theme" : "light-theme"}`}>
        <div className="content-fade" aria-hidden="true" />

        {/* calm ambient layer: dot grid + three slow gradient orbs */}
        <div className="ambient" aria-hidden="true">
          <span className="orb orb-a" />
          <span className="orb orb-b" />
          <span className="orb orb-c" />
        </div>

        <About />
        <Skills />
        <Work />
        <Hint />
        <Contact />

        <footer className="footer">
          <span>© {new Date().getFullYear()} Pushkar Mishra</span>
          <a
            className="footer-hint"
            href="https://hintly.in"
            target="_blank"
            rel="noopener noreferrer"
          >
            Also building HINT — hintly.in
          </a>
          <span>Crafted with care — web-slung across the multiverse.</span>
        </footer>
      </main>
    </div>
  );
}

export default App;
