import React, { useEffect, useRef } from "react";
import * as THREE from "three";
import "./EarthJourney.css";

/* =====================================================================
   EARTH JOURNEY — replaces the old "below the clouds" sky section.
   Scroll turns the globe to Noida, then draws a dotted arc to the visitor
   (IP-based, approximate, nothing stored). Textures live in /public/earth.
   ===================================================================== */
export default function EarthJourney() {
  const rootRef = useRef(null);

  useEffect(() => {
    const rootEl = rootRef.current;
    if (!rootEl) return;
    const trackEl = rootEl;                                  // tall scroll track
    const stageEl = rootEl.querySelector(".ej-stage");       // sticky viewport-sized stage
    const $ = (id) => rootEl.querySelector("#ej-" + id);
    let dead = false;
    let cleanup = () => {};
    const prevCM = THREE.ColorManagement.enabled;
    THREE.ColorManagement.enabled = false;                   // keep the exact look of the approved preview


    /* ---------- config ---------- */
    const R = 2;                                   // globe radius
    const ME = {name:'Noida', lat:28.5355, lon:77.3910};
    const START = {lat:12, lon:-95};               // view before scroll (the Americas, like the reference)
    const FOV = 40, TANF = Math.tan(FOV/2*Math.PI/180);
    const REDUCED = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    let SW=Math.max(1,stageEl.clientWidth), SH=Math.max(1,stageEl.clientHeight);   // stage size (not the window)

    /* ---------- helpers ---------- */
    const clamp=(x,a=0,b=1)=>Math.min(b,Math.max(a,x));
    const lerp=(a,b,t)=>a+(b-a)*t;
    const easeIO=t=>t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2;
    const easeO=t=>1-Math.pow(1-t,3);
    const fmt=n=>Math.round(n).toLocaleString('en-IN');
    function latLonToVec3(lat,lon,r){
      const phi=(90-lat)*Math.PI/180, th=(lon+180)*Math.PI/180;
      return new THREE.Vector3(-r*Math.sin(phi)*Math.cos(th), r*Math.cos(phi), r*Math.sin(phi)*Math.sin(th));
    }
    function haversineKm(a,b){
      const t=Math.PI/180, dLat=(b.lat-a.lat)*t, dLon=(b.lon-a.lon)*t;
      const h=Math.sin(dLat/2)**2+Math.cos(a.lat*t)*Math.cos(b.lat*t)*Math.sin(dLon/2)**2;
      return 2*6371*Math.asin(Math.sqrt(h));
    }
    function faceAngles(v){            // rotation that brings direction v to face the camera (+z)
      const n=v.clone().normalize();
      return {ry:Math.atan2(-n.x,n.z), rx:Math.asin(clamp(n.y,-1,1))};
    }

    /* ---------- three scene ---------- */
    const host=$('canvasHost');
    const scene=new THREE.Scene();
    const camera=new THREE.PerspectiveCamera(FOV,SW/SH,0.01,100);   // tiny near-plane: close visitors zoom right down to the surface
    const renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});
    renderer.setPixelRatio(Math.min(devicePixelRatio,2));
    renderer.setSize(SW,SH);
    renderer.outputColorSpace=THREE.LinearSRGBColorSpace;   // same look as the preview (three r128, no colour management)
    host.appendChild(renderer.domElement);

    const tex=new THREE.TextureLoader();
    const maxAniso=renderer.capabilities.getMaxAnisotropy();
    function T(src){const t=tex.load(src);t.anisotropy=maxAniso;return t;}
    const BASE=(process.env.PUBLIC_URL||'')+'/earth/';
    const dayMap=T(BASE+'day.jpg'), cloudMap=T(BASE+'clouds.png'), normalMap=T(BASE+'normal.jpg'), specMap=T(BASE+'specular.jpg');

    const root=new THREE.Group(); scene.add(root);          // positioned on screen
    const earth=new THREE.Group(); root.add(earth);          // rotated by scroll

    const globe=new THREE.Mesh(
      new THREE.SphereGeometry(R,96,96),
      new THREE.MeshPhongMaterial({
        map:dayMap, normalMap, normalScale:new THREE.Vector2(.55,.55),
        specularMap:specMap, specular:new THREE.Color(0x0a1822), shininess:30,
        emissive:new THREE.Color(0x0f1f2e), emissiveMap:dayMap          // keeps the surface bright, never dull
      }));
    earth.add(globe);

    const clouds=new THREE.Mesh(
      new THREE.SphereGeometry(R*1.013,96,96),
      new THREE.MeshPhongMaterial({map:cloudMap,transparent:true,opacity:.82,depthWrite:false,
        emissive:new THREE.Color(0x667788),shininess:0}));
    earth.add(clouds);

    // outer halo (stays screen-aligned, does not rotate)
    const halo=new THREE.Mesh(
      new THREE.SphereGeometry(R*1.2,64,64),
      new THREE.ShaderMaterial({
        transparent:true,side:THREE.BackSide,blending:THREE.AdditiveBlending,depthWrite:false,
        uniforms:{glow:{value:new THREE.Color(0x55c8ff)},k:{value:1}},
        vertexShader:`varying vec3 vN;void main(){vN=normalize(normalMatrix*normal);gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}`,
        fragmentShader:`uniform vec3 glow;uniform float k;varying vec3 vN;void main(){float i=pow(max(0.0,0.62-dot(vN,vec3(0.0,0.0,1.0))),3.2);gl_FragColor=vec4(glow,1.0)*i*1.5*k;}`
      }));
    root.add(halo);

    // inner rim light
    const rim=new THREE.Mesh(
      new THREE.SphereGeometry(R*1.02,96,96),
      new THREE.ShaderMaterial({
        transparent:true,blending:THREE.AdditiveBlending,depthWrite:false,
        uniforms:{glow:{value:new THREE.Color(0x66d4ff)}},
        vertexShader:`varying vec3 vN;varying vec3 vV;void main(){vN=normalize(normalMatrix*normal);vec4 mv=modelViewMatrix*vec4(position,1.0);vV=normalize(-mv.xyz);gl_Position=projectionMatrix*mv;}`,
        fragmentShader:`uniform vec3 glow;varying vec3 vN;varying vec3 vV;void main(){float f=pow(1.0-max(0.0,dot(vN,vV)),2.6);gl_FragColor=vec4(glow,1.0)*f*0.85;}`
      }));
    root.add(rim);

    scene.add(new THREE.AmbientLight(0xffffff,.5*Math.PI));
    const sun=new THREE.DirectionalLight(0xfff6e8,.62*Math.PI); sun.position.set(-4,3,6); scene.add(sun);


    /* ---------- pins, arc ---------- */
    const pinsEl=$('pins');
    function makePin(cls,text){
      const d=document.createElement('div'); d.className='pin '+cls;
      d.innerHTML='<div class="dot"></div><div class="label"></div>';
      d.querySelector('.label').textContent=text; pinsEl.appendChild(d); return d;
    }
    const haloMat=halo.material;
    [halo.material,rim.material].forEach(m=>{            // exactly the blend three r128 used (colour AND alpha scaled by alpha) -> same soft glow as the preview
      m.blending=THREE.CustomBlending; m.blendEquation=THREE.AddEquation;
      m.blendSrc=THREE.SrcAlphaFactor; m.blendDst=THREE.OneFactor;
      m.blendSrcAlpha=THREE.SrcAlphaFactor; m.blendDstAlpha=THREE.OneFactor;
    });
    const pinMe=makePin('me','Noida · where I build');
    const pinYou=makePin('you','You');
    const chip=$('chip');
    const vMe=latLonToVec3(ME.lat,ME.lon,R*1.004);
    let vYou=null, arcCurve=null;

    const FAR_SIDE_ANG=2.3;                       // radians (~14,650 km): beyond this, both points can't sit comfortably on one face
    const state={
      mode:'unknown',            // 'ok' | 'unknown'
      you:null, city:'', dist:0, ang:0,
      cTarget:null, zEnd:5.4, farSide:false, merged:false, hasArc:false, near:false, lpx:999
    };

    function slerpUnit(a,b,t){
      const d=clamp(a.dot(b),-1,1), om=Math.acos(d);
      const s=Math.sin(om);
      if(om<1e-4||s<1e-4) return a.clone();
      return a.clone().multiplyScalar(Math.sin((1-t)*om)/s).add(b.clone().multiplyScalar(Math.sin(t*om)/s));
    }
    const SZ_MIN=0.58, D_NEAR=238, D_FAR=12000;     // Jaipur-sized dots (~238 km) are the floor -> full size at ~12,000 km (Buenos Aires)
    function sizeFor(d){                             // smooth, log-spaced: every distance gets its own size
      const t=clamp((Math.log(Math.max(d,D_NEAR))-Math.log(D_NEAR))/(Math.log(D_FAR)-Math.log(D_NEAR)));
      return lerp(SZ_MIN,1,t*t*(3-2*t));
    }
    let arcPts=null, arcUni=null;
    function disposeArc(){
      if(arcPts){earth.remove(arcPts);arcPts.geometry.dispose();arcPts.material.dispose();}
      arcPts=null; arcCurve=null; arcUni=null;
    }
    function buildArc(){
      disposeArc();
      const a=vMe.clone().normalize(), b=vYou.clone().normalize();
      const chord=2*R*Math.sin(state.ang/2);
      const arcH=Math.min(R*clamp(state.ang/1.5,0.03,1)*0.34, 0.3*chord);   // short hops get a proportionally short arc, not a spike
      const pts=[];
      for(let i=0;i<=96;i++){
        const t=i/96;
        pts.push(slerpUnit(a,b,t).multiplyScalar(R*1.006+arcH*Math.sin(Math.PI*t)));
      }
      arcCurve=new THREE.CatmullRomCurve3(pts);
      const sz=sizeFor(state.dist);                                   // dot size follows distance smoothly
      const N=state.near?Math.round(clamp(state.lpx/(14*sz*1.3),2,170)):Math.round(clamp(arcCurve.getLength()/(0.07*sz),12,170));  // spacing follows the dot size
      const pos=new Float32Array(N*3), u=new Float32Array(N);
      for(let i=0;i<N;i++){
        const t=i/(N-1), p=arcCurve.getPoint(t);
        pos.set([p.x,p.y,p.z],i*3); u[i]=t;
      }
      const g=new THREE.BufferGeometry();
      g.setAttribute('position',new THREE.BufferAttribute(pos,3));
      g.setAttribute('u',new THREE.BufferAttribute(u,1));
      arcUni={uProg:{value:0},uTime:{value:0},uSize:{value:7.5*sz*renderer.getPixelRatio()},uCap:{value:state.near?2.4:99}};
      const m=new THREE.ShaderMaterial({
        uniforms:arcUni,transparent:true,depthWrite:false,blending:THREE.NormalBlending,
        vertexShader:`attribute float u;varying float vU;uniform float uSize;uniform float uCap;
          void main(){vU=u;vec4 mv=modelViewMatrix*vec4(position,1.0);gl_PointSize=uSize*min(6.0/-mv.z,uCap);gl_Position=projectionMatrix*mv;}`,
        fragmentShader:`varying float vU;uniform float uProg;uniform float uTime;
          void main(){
            if(vU>uProg) discard;
            float d=length(gl_PointCoord-0.5); if(d>0.5) discard;
            float wave=fract(vU*5.0-uTime*0.30);                 // light pulses travelling Noida -> visitor
            float flow=pow(1.0-wave,2.2);
            float head=smoothstep(0.07,0.0,uProg-vU);
            vec3 inner=mix(vec3(1.0,0.82,0.36),vec3(1.0),clamp(head+flow*0.6,0.0,1.0));
            vec3 col=mix(vec3(0.02,0.10,0.28),inner,smoothstep(0.50,0.30,d));   // dark rim keeps the dots readable on pale land
            gl_FragColor=vec4(col,smoothstep(0.5,0.42,d));
          }`});
      arcPts=new THREE.Points(g,m); arcPts.frustumCulled=false; arcPts.renderOrder=10; earth.add(arcPts);
    }

    /* ---------- visitor setup (called on load, and by the preview selector) ---------- */
    function setVisitorCore(you){           // you = {lat,lon,city} or null
      const startV=latLonToVec3(START.lat,START.lon,1);
      state.start=faceAngles(startV);
      if(!you){
        state.mode='unknown'; state.you=null; state.near=false; [pinMe,pinYou].forEach(e=>e.style.setProperty('--ps',1)); state.hasArc=false; state.merged=false; vYou=null; disposeArc();
        state.cTarget=vMe.clone().normalize(); state.zEnd=5.4; state.farSide=false;
        state.dist=0; state.ang=0;
        pinYou.style.display='none'; pinMe.classList.remove('merged');
        pinMe.querySelector('.label').textContent='Noida · where I build';
        pinMe.dataset.text='Noida · where I build';
        writeCopy(); return;
      }
      state.mode='ok'; state.you=you; state.city=you.city||''; state.near=false;
      state.dist=haversineKm(ME,you);
      state.ang=state.dist/6371;
      vYou=latLonToVec3(you.lat,you.lon,R*1.004);
      state.merged=state.dist<12;                           // practically the same spot
      state.hasArc=!state.merged;
      state.farSide=state.ang>FAR_SIDE_ANG;
      const mid=vMe.clone().normalize().add(vYou.clone().normalize());
      if(state.merged){ state.cTarget=vMe.clone().normalize(); state.zEnd=4.8; }
      else if(state.farSide){ state.cTarget=vYou.clone().normalize(); state.zEnd=6.4; }     // land ON the visitor; Noida becomes an edge marker
      else{
        state.cTarget=(mid.length()<1e-3?vMe.clone():mid).normalize();                       // midpoint
        const h=state.ang/2;                                                                 // fit the two points on screen: zoom right in when close, pull back when far
        const zRaw=R*Math.sin(h)/(0.5*TANF)+R*Math.cos(h);
        state.near=zRaw<5.2;
        state.zEnd=state.near?Math.max(zRaw,3.8):Math.min(zRaw,10.9);          // never closer than ~the Dubai view: stays sharp
        state.lpx=2*R*Math.sin(h)/(2*(state.zEnd-R)*TANF)*SH;           // approx on-screen length of the arc (px)
      }
      const ps=sizeFor(state.dist);
      [pinMe,pinYou].forEach(e=>e.style.setProperty('--ps',ps));
      pinYou.style.display='';
      pinYou.querySelector('.label').textContent='You'+(state.city?' · '+state.city:'')+' (approx.)';
      pinMe.classList.toggle('merged',false);
      pinYou.classList.toggle('merged',state.merged);
      pinMe.querySelector('.label').textContent=state.merged?'You’re right here, near Noida':'Noida · where I build';
      pinMe.dataset.text=pinMe.querySelector('.label').textContent;
      pinMe.dataset.limbText='Noida · '+fmt(state.dist)+' km that way';
      if(state.hasArc) buildArc(); else disposeArc();
      writeCopy();
    }

    function setVisitor(you){ setVisitorCore(you); }

    /* ---------- copy based on distance ---------- */
    function copyFor(d){
      const k=fmt(d);
      if(d<12)    return {t:'You’re practically next door.',s:'Within a few kilometres of where I build. Come say hello — chai is on me.'};
      if(d<60)    return {t:`We are just ${k} km apart.`,s:'Practically neighbours. Let’s meet over chai and build something good.'};
      if(d<600)   return {t:`We are just ${k} km apart.`,s:'Close enough for a same-day meeting. Tell me what you’re building.'};
      if(d<2500)  return {t:`We are only ${k} km apart.`,s:'One short flight away, and one message closer.'};
      if(d<8000)  return {t:`${k} km apart — and still one message away.`,s:'Different time zones, same screen. I ship for clients across the world.'};
      return {t:`${k} km apart — opposite ends of the map.`,s:'Distance doesn’t slow good work down. I deliver across time zones, on time.'};
    }
    function writeCopy(){
      if(state.mode!=='ok'){
        $('finalTitle').textContent='Wherever you are, I’m one message away.';
        $('finalSub').textContent='Based in Noida, India — building games and web experiences for people everywhere.';
        $('fine').textContent='';
        $('routeTxt').textContent='Locating you…';
        return;
      }
      const c=state.farSide?{t:'We’re on opposite sides of the world.',s:`${fmt(state.dist)} km apart — nearly the whole planet between us. Time zones have never stopped me from delivering.`}:copyFor(state.dist);
      $('finalTitle').textContent=c.t; $('finalSub').textContent=c.s;
      $('fine').textContent='Your location is approximate (from your IP address, city-level at best). Nothing is stored.';
      $('routeTxt').textContent='Noida → '+(state.city||'you');
    }

    /* ---------- IP lookup ---------- */
    async function lookupIP(){
      const tries=[
        async()=>{const r=await fetch('https://ipwho.is/');const j=await r.json();if(!j.success)throw 0;return {lat:j.latitude,lon:j.longitude,city:j.city};},
        async()=>{const r=await fetch('https://ipapi.co/json/');const j=await r.json();if(!j.latitude)throw 0;return {lat:j.latitude,lon:j.longitude,city:j.city};}
      ];
      for(const f of tries){try{const v=await f();if(isFinite(v.lat)&&isFinite(v.lon))return v;}catch(e){ /* try next provider */ }}
      return null;
    }
    setVisitor(null);                          // start with fallback, then upgrade when lookup returns
    lookupIP().then(v=>{ if(!dead) setVisitor(v); });

    /* ---------- scroll drives the timeline (smoothed, so nothing ever hard-cuts) ---------- */
    function scrollP(){const r=trackEl.getBoundingClientRect();const m=trackEl.offsetHeight-SH*1.5;return m>0?clamp(-r.top/m):0;}   /* last 0.5 screen = hold on the final card */
    let sp=0;                                      // smoothed scroll progress 0..1
    const TT=6.3;                                  // timeline length in "seconds"; the phases below are laid out on it

    /* ---------- layout helpers ---------- */
    const setOp=(el,o)=>{el.style.opacity=o.toFixed(3);el.style.pointerEvents=o>.6?'auto':'none';};
    let C={x:0,y:0}, rPx=300;                                      // globe centre + radius on screen (px)
    function layout(z){
      // Pan with a projection offset (not by moving the globe) so the chosen spot sits dead-centre of the globe's face.
      const W=SW,H=SH,aspect=W/H;
      const rFrac=Math.tan(Math.asin(R/z))/TANF;
      let nx=0,ny=0;
      if(aspect>=1.05) nx=clamp(Math.max(0.30,-0.22+rFrac/aspect),0.30,0.50);
      else ny=0.26;
      camera.setViewOffset(W,H,-nx*W/2,ny*H/2,W,H);
    }
    function projectToScreen(v){
      const p=v.clone().project(camera);
      return {x:(p.x*.5+.5)*SW,y:(1-(p.y*.5+.5))*SH};
    }
    function placePin(el,vec,vis,limbOK){
      const w=vec.clone().applyMatrix4(earth.matrixWorld);
      const n=w.clone().normalize();
      const facing=n.dot(camera.position.clone().sub(w).normalize());
      let s=projectToScreen(w), op=vis*clamp((facing-0.04)/0.2), limb=false;
      if(limbOK&&facing<0.2){                                      // far side: park the marker on the globe's edge, pointing the way
        const dx=s.x-C.x, dy=s.y-C.y, len=Math.hypot(dx,dy)||1;
        s={x:C.x+dx/len*rPx,y:C.y+dy/len*rPx}; op=vis; limb=true;
      }
      if(el._limb!==limb){el._limb=limb;el.classList.toggle('limb',limb);
        if(el.dataset.text) el.querySelector('.label').textContent=limb?el.dataset.limbText:el.dataset.text;}
      el.classList.toggle('flipL',limb&&s.x>C.x);
      el.style.transform=`translate(${s.x}px,${s.y}px)`;
      el.style.opacity=op.toFixed(3);
      return facing;
    }

    /* ---------- the sequence, driven by scroll ----------
       T 0.0–2.4  Earth turns to Noida and settles on it
       T 2.4–5.1  camera glides + dotted arc flows out to the visitor (midpoint view, or lands on the visitor if they're on the far side)
       T 5.2+     message + Contact Me; keep scrolling and it just stays                    */
    function frame(){
      const pRaw=scrollP();
      sp=REDUCED?pRaw:sp+(pRaw-sp)*0.075;
      if(Math.abs(pRaw-sp)<0.0003) sp=pRaw;
      const T=sp*TT;
      const wide=SW/SH>=1.05;
      const spin=easeIO(clamp(T/2.4));
      const gl=easeIO(clamp((T-2.4)/2.7));
      const arcP=state.farSide?gl:easeO(clamp((T-2.7)/2.3));
      const card=easeO(clamp((T-5.2)/0.7));
      const intro=1-clamp(T/0.5);
      const trace=clamp((T-0.5)/0.4)*(1-clamp((T-5.0)/0.4));

      // orientation
      if(T<2.4){
        const S=state.start, N=faceAngles(vMe);
        let d=(N.ry-S.ry)%(Math.PI*2); if(d<0)d+=Math.PI*2;      // always turn eastward
        earth.rotation.set(lerp(S.rx,N.rx,spin),S.ry+d*spin,0);
      }else{
        const v=slerpUnit(vMe.clone().normalize(),state.cTarget,gl), f=faceAngles(v);
        earth.rotation.set(f.rx,f.ry,0);
      }
      clouds.rotation.y=Math.min(T,6)*0.05;                        // clouds drift only while the sequence plays

      // camera
      const zm=wide?1:1.25, zHero=wide?7.2:9.4, zN=5.8*zm;
      const zE=state.near?R+(state.zEnd-R)*(1+(zm-1)*clamp((state.zEnd-2)/3.2)):state.zEnd*zm;
      let zGlide=lerp(zN,zE,gl);
      if(state.near){                                                // zoom feels even when diving close: ease in log-distance
        const zLog=R+Math.exp(lerp(Math.log(zN-R),Math.log(zE-R),gl));
        zGlide=lerp(zGlide,zLog,clamp((5.0-state.zEnd)/1.0));
      }
      const z=T<2.4?lerp(zHero,zN,spin):zGlide+(state.farSide?1.6*Math.sin(Math.PI*gl):0);
      camera.position.set(0,0,z);
      layout(z);
      root.updateMatrixWorld(true);

      // globe centre/radius on screen (for the rings and edge markers)
      C=projectToScreen(root.position.clone());
      rPx=Math.tan(Math.asin(R/camera.position.distanceTo(root.position)))/TANF*(SH/2);

      // arc (dotted, flowing)
      if(arcUni){ arcUni.uProg.value=arcP*1.002; arcUni.uTime.value=REDUCED?0:performance.now()/1000; }

      // pins
      earth.updateMatrixWorld();
      const limbOK=state.farSide&&T>=2.4;
      placePin(pinMe,vMe,clamp((T-1.7)/0.5),limbOK);
      if(vYou) placePin(pinYou,vYou,clamp((T-2.6)/0.4),false);

      // distance chip at the arc midpoint (hidden for very close visitors and when it faces away)
      if(arcCurve&&state.hasArc){
        const w=arcCurve.getPoint(0.5).clone().applyMatrix4(earth.matrixWorld);
        const facing=w.clone().normalize().dot(camera.position.clone().sub(w).normalize());
        const s=projectToScreen(w);
        chip.style.transform=`translate(${s.x}px,${s.y}px) translate(-50%,-150%)`;
        chip.textContent=fmt(state.dist)+' km';
        chip.style.opacity=(clamp((arcP-0.85)/0.15)*clamp((facing-0.05)/0.2)).toFixed(3);
      } else chip.style.opacity=0;

      haloMat.uniforms.k.value=clamp((z-2.6)/1.2); halo.visible=z>2.4;
      // halo rings follow the globe (fade out when the globe is bigger than the screen)
      const r1=$('ring1'), r2=$('ring2');
      r1.style.opacity=r2.style.opacity=clamp((3000-rPx)/1200).toFixed(3);
      r1.style.left=r2.style.left=C.x+'px'; r1.style.top=r2.style.top=C.y+'px';
      r1.style.width=r1.style.height=(rPx*2*1.17)+'px';
      r2.style.width=r2.style.height=(rPx*2*1.36)+'px';

      // copy layers
      setOp($('sIntro'),intro);
      setOp($('sTrace'),trace);
      setOp($('sFinal'),card);
      $('countNum').textContent=state.mode==='ok'?fmt(state.dist*arcP):'—';
      $('railFill').style.height=(scrollP()*100)+'%';
      $('fade').style.opacity=easeIO(clamp((sp-0.8)/0.2)).toFixed(3);

      renderer.render(scene,camera);
    }
    let raf=0, visible=true;
    function loop(){ if(dead||!visible){raf=0;return;} frame(); raf=requestAnimationFrame(loop); }
    function onResize(){
      SW=Math.max(1,stageEl.clientWidth); SH=Math.max(1,stageEl.clientHeight);
      camera.aspect=SW/SH; camera.updateProjectionMatrix(); renderer.setSize(SW,SH);
      if(state.mode==='ok'&&state.you) setVisitorCore(state.you);   // zoom depends on the viewport
    }
    const ro=new ResizeObserver(onResize); ro.observe(stageEl);
    const io=new IntersectionObserver(es=>{ visible=es[0].isIntersecting; if(visible&&!raf&&!dead) raf=requestAnimationFrame(loop); },{rootMargin:'200px 0px'});
    io.observe(trackEl);
    raf=requestAnimationFrame(loop);
    cleanup=()=>{
      dead=true; cancelAnimationFrame(raf); ro.disconnect(); io.disconnect();
      disposeArc();
      scene.traverse(o=>{ if(o.geometry) o.geometry.dispose(); if(o.material){ [].concat(o.material).forEach(m=>{ ['map','normalMap','specularMap','emissiveMap'].forEach(k=>m[k]&&m[k].dispose()); m.dispose(); }); } });
      renderer.dispose(); if(renderer.domElement.parentNode) renderer.domElement.parentNode.removeChild(renderer.domElement);
      pinsEl.innerHTML='';
      THREE.ColorManagement.enabled=prevCM;
    };


    return () => { cleanup(); };
  }, []);

  return (
    <section className="ej" ref={rootRef} aria-label="Where you are, and how far we are apart">
      <div className="ej-stage">
        <div className="ej-ring ej-r2" id="ej-ring2" />
        <div className="ej-ring" id="ej-ring1" />
        <div className="ej-canvas" id="ej-canvasHost" />
        <div className="ej-pins" id="ej-pins" />
        <div className="ej-scrim" />
        <div className="ej-fade" id="ej-fade" />
        <div className="ej-chip" id="ej-chip" style={{ opacity: 0 }} />

        <div className="ej-copy">
          <div className="ej-layer" id="ej-sIntro">
            <h1>Wherever you’re reading this from.</h1>
            <p className="ej-lede">Keep scrolling — the Earth will turn to find you, then show how far apart we really are.</p>
            <div className="ej-hint"><i /><span>Scroll to begin</span></div>
          </div>
          <div className="ej-layer" id="ej-sTrace">
            <div className="ej-route" id="ej-routeTxt">Noida → …</div>
            <div className="ej-count"><span id="ej-countNum">0</span><small>km</small></div>
          </div>
          <div className="ej-layer" id="ej-sFinal">
            <h2 id="ej-finalTitle">We are just … km apart.</h2>
            <p className="ej-lede" id="ej-finalSub" />
            <a className="ej-cta" id="ej-cta" href="#contact">Contact Me <span className="ej-arr">→</span></a>
            <p className="ej-fine" id="ej-fine">Your location is approximate (from your IP address, city-level at best). Nothing is stored.</p>
          </div>
        </div>

        <div className="ej-rail"><b id="ej-railFill" /></div>
      </div>
    </section>
  );
}
